        static uint CRC32(string input, bool toLower)
        {
            uint crc = 0xFFFFFFFF;

            foreach (byte b in Encoding.ASCII.GetBytes(input))
            {
                byte ch = toLower ? (byte)char.ToLower((char)b) : (byte)char.ToUpper((char)b);
                crc = crcTable[(crc ^ ch) & 0xFF] ^ (crc >> 8);
            }

            return crc ^ 0xFFFFFFFF;
        }

        static uint ReverseBytes(uint value)
        {
            return ((value & 0xFF) << 24) |
                   ((value & 0xFF00) << 8) |
                   ((value & 0xFF0000) >> 8) |
                   ((value & 0xFF000000) >> 24);
        }

        static void Main(string[] args)
        {
            string[] testStrings = new string[]
            {
                "./ee_files/config_preload.lua"
            };

            int loop = 0;

            foreach (var s in testStrings)
            {
                uint hashUpper = CRC32(s, false);
                uint hashLower = CRC32(s, true);
                uint hashRevUpper = ReverseBytes(hashUpper);
                uint hashRevLower = ReverseBytes(hashLower);

                foreach (var h in hexList)
                {
                    if (hashUpper == h)
                    {
                        Console.WriteLine($"hashUpper:{h:X8}={s} @{loop}");
                        Console.ReadLine();
                    }

                    if (hashLower == h)
                    {
                        Console.WriteLine($"hashLower:{h:X8}={s} @{loop}");
                        Console.ReadLine();
                    }

                    if (hashRevUpper == h)
                    {
                        Console.WriteLine($"hashRevUpper:{h:X8}={s} @{loop}");
                        Console.ReadLine();
                    }

                    if (hashRevLower == h)
                    {
                        Console.WriteLine($"hashRevLower:{h:X8}={s} @{loop}");
                        Console.ReadLine();
                    }

                    loop++;
                }
            }
        }
    }
